"""Pure invoice validation and event sorting utilities.

This module intentionally contains only pure functions: no I/O, no global
mutation, no randomness, and no external dependencies. Each function accepts
plain data (dicts, lists, strings, ints) and returns a new value.

Ledger record shape assumed throughout:
    {
        "id": "R000000",
        "account": "A00",
        "status": "paid",
        "qty": 1,
        "unit_cents": 137,
        "note": "verified ledger entry",
    }
"""

from __future__ import annotations

from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple


# ---------------------------------------------------------------------------
# 1. Basic record validation
# ---------------------------------------------------------------------------

def is_record_dict(record: Any) -> bool:
    """Return True if record is a dict-like mapping."""
    return isinstance(record, dict)


def has_required_fields(record: Dict[str, Any]) -> bool:
    """Return True if record contains all required ledger fields."""
    required = {"id", "account", "status", "qty", "unit_cents", "note"}
    return isinstance(record, dict) and required.issubset(record.keys())


def validate_record_id(record_id: Any) -> bool:
    """Return True if record_id is a non-empty string starting with 'R'."""
    return isinstance(record_id, str) and record_id.startswith("R") and len(record_id) > 1


def validate_account(account: Any) -> bool:
    """Return True if account is a non-empty string."""
    return isinstance(account, str) and len(account) > 0


def validate_status(status: Any) -> bool:
    """Return True if status is one of the accepted invoice statuses."""
    return status in {"paid", "pending", "void", "refunded"}


def validate_qty(qty: Any) -> bool:
    """Return True if qty is a positive integer."""
    return isinstance(qty, int) and not isinstance(qty, bool) and qty > 0


def validate_unit_cents(unit_cents: Any) -> bool:
    """Return True if unit_cents is a non-negative integer."""
    return isinstance(unit_cents, int) and not isinstance(unit_cents, bool) and unit_cents >= 0
